const b = $input.first().json.body || $input.first().json;
const s = v => String(v == null ? '' : v).trim();
const contact = s(b.phone || b.contact_value || b.email);
const isEmail = /@/.test(contact);
let digits = contact.replace(/[^0-9+]/g, '');
const location = s(b.location);
const intl = /^\+/.test(digits) && !/^\+91/.test(digits);
return [{ json: {
  name: s(b.name) || 'Voice visitor',
  contact_method: isEmail ? 'email' : 'phone',
  contact_value: isEmail ? contact : digits,
  segment: s(b.segment) || (intl ? 'international' : 'local'),
  service_interest: s(b.service_interest) || 'General enquiry',
  qualification_data: {
    request: 'call_back',
    channel: 'voice',
    best_time_to_call: s(b.best_time_to_call) || 'anytime',
    business_type: s(b.business_type),
    location,
    goal: s(b.goal),
    notes: s(b.notes)
  },
  conversation_id: s(b.conversation_id) || ('voice-' + Date.now())
} }];
